"""Neo4j and Elasticsearch run their vendors' memory rules (DECISIONS #202; vendor_memory.py).

Run with `uv run python -m pytest test_vendor_memory.py -q` from this directory. Held, each by the failure it would cause:

  * the Neo4j table in code equals the tool output committed in `neo4j_memory_recommendation.json` (generated by
    `python3 vendor_memory.py --regenerate`, never typed), re-parsed here from the raw output, for every cap in the tier table;
  * the file names the image digest every Neo4j arm pins and the command the code states, and the tool's initial heap equals its max;
  * the runner passes Neo4j the table's heap and page cache, and its arms keep initial heap = max heap;
  * Elasticsearch's heap at every tier is at most half the cap and under the compressed-oops threshold, `-Xms` = `-Xmx`,
    and deep10m moved from 24g to 18g;
  * the heap observed in a container's environment is read back exactly (3600m is not 3g).
"""
import json
import os

import pytest

import runner
import vendor_memory as vm

FILE = json.load(open(vm.NEO4J_RECOMMENDATION_FILE))
NEO4J_ARMS = [b for b in runner.BACKENDS if vm.is_neo4j(b)]
ES_ARMS = [b for b in runner.BACKENDS if vm.is_elasticsearch(b)]
CAPS = sorted(set(runner.MEM_BY_SCALE.values()), key=vm._gib)


def test_table_covers_every_cap_in_the_tier_table():
    assert set(vm.NEO4J_MEMORY) == set(CAPS) == set(FILE["caps"])


@pytest.mark.parametrize("cap", CAPS)
def test_table_equals_the_committed_tool_output(cap):
    rec = FILE["caps"][cap]
    hi, hm, pc = vm.parse_recommendation(rec["output"])      # the raw text, not the summary fields beside it
    assert hi == hm, "the tool recommends initial heap = max heap"
    assert (hm, pc) == (rec["heap_max"], rec["pagecache"]) == vm.NEO4J_MEMORY[cap]


def test_file_names_the_image_and_the_command():
    assert FILE["image"] == "neo4j@" + vm.NEO4J_IMAGE_DIGEST
    assert FILE["command"] == vm.NEO4J_RECOMMENDATION_COMMAND
    for b in NEO4J_ARMS:
        img = runner.BACKENDS[b]["server_image"]
        if img == "dbbench:composed":     # the composed stack builds its Neo4j half FROM the same digest
            assert vm.NEO4J_IMAGE_DIGEST in open(os.path.join(vm.HERE, "Dockerfile.composed")).read()
        else:
            assert img == FILE["image"], b


def test_neo4j_arms_keep_initial_heap_equal_to_max():
    assert NEO4J_ARMS
    for b in NEO4J_ARMS:
        env = " ".join(runner.BACKENDS[b]["server_env"])
        assert "NEO4J_server_memory_heap_initial__size={heap}" in env, b
        assert "NEO4J_server_memory_heap_max__size={heap}" in env, b
        assert "NEO4J_server_memory_pagecache_size={pagecache}" in env, b


@pytest.mark.parametrize("scale", sorted(runner.HEAP_BY_SCALE))
def test_runner_gives_neo4j_the_tool_numbers(scale):
    cap = runner.MEM_BY_SCALE[scale]
    for b in NEO4J_ARMS:
        assert runner.heap_for(b, scale) == vm.NEO4J_MEMORY[cap][0]
        assert runner._pagecache_for(runner.mem_bytes(cap), runner.heap_for(b, scale), b, cap) == vm.NEO4J_MEMORY[cap][1]


def test_other_engines_keep_the_tier_heap_and_the_formula():
    for scale in runner.HEAP_BY_SCALE:
        assert runner.heap_for("arcadedb_graph", scale) == runner.HEAP_BY_SCALE[scale]
        assert runner.heap_for("qdrant_dense", scale) == runner.HEAP_BY_SCALE[scale]
    # the formula (heap, 1 GiB reserve, floor 512m) still answers a caller that names no Neo4j arm
    assert runner._pagecache_for(runner.mem_bytes("8g"), "4g") == "3.0g"


def test_override_switches_the_vendor_rule_off(monkeypatch):
    monkeypatch.setattr(runner, "VENDOR_MEMORY", False)
    assert runner.heap_for("neo4j_graph", "small") == runner.HEAP_BY_SCALE["small"]
    assert runner._pagecache_for(runner.mem_bytes("16g"), "8g", "neo4j_graph", "16g") == "7.0g"


def test_elasticsearch_heap_rule():
    assert ES_ARMS
    for scale, cap in runner.MEM_BY_SCALE.items():
        if scale not in runner.HEAP_BY_SCALE:
            continue
        h = vm._gib(runner.heap_for("elasticsearch_dense", scale))
        assert h <= 0.5 * vm._gib(cap), scale
        assert h <= vm.ES_HEAP_OOPS_CEILING_GIB, scale
        assert h <= vm._gib(runner.HEAP_BY_SCALE[scale]), scale     # never above what it ran at
    assert runner.heap_for("elasticsearch_dense", "deep10m") == "18g"      # was 24g in 36g
    for scale in ("micro", "tiny", "small", "medium", "large"):             # the half-cap tiers do not move
        assert runner.heap_for("elasticsearch_sparse", scale) == runner.HEAP_BY_SCALE[scale]


def test_elasticsearch_arms_keep_xms_equal_to_xmx():
    for b in ES_ARMS:
        assert "ES_JAVA_OPTS=-Xms{heap} -Xmx{heap}" in " ".join(runner.BACKENDS[b]["server_env"]), b


@pytest.mark.parametrize("heap,expect", [("3600m", "3600m"), ("13800m", "13800m"), ("4096m", "4g"), ("12g", "12g")])
def test_observed_heap_is_read_back_exactly(monkeypatch, heap, expect):
    env = json.dumps(["NEO4J_server_memory_heap_initial__size=" + heap, "NEO4J_server_memory_heap_max__size=" + heap])
    monkeypatch.setattr(runner, "sh", lambda cmd, *a, **k: env if "{{json .Config.Env}}" in cmd else "")
    assert runner.observe_server("cid").get("server_heap") == expect


def test_a_vendor_rule_row_is_stamped_and_judged_by_its_own_rule(capsys):
    import fairness_check as fc
    def row(be, heap, **kw):
        return dict(lane="l2", scale="small", backend=be, mem_cap="16g", heap=heap, server_heap=heap, server_mem_cap="16g",
                    mem_split="full+client", client_mem_cap="8g", rep=1, **kw)
    ok = [row("neo4j_graph", "5g", vendor_memory="x"), row("arcadedb_graph", "8g")]
    assert fc.check_envelope(ok) == 0
    bad = [row("neo4j_graph", "8g", vendor_memory="x"), row("arcadedb_graph", "8g")]
    assert fc.check_envelope(bad) == 1
    assert "the vendor rule gives 5g" in capsys.readouterr().out
    old = [row("neo4j_graph", "8g"), row("arcadedb_graph", "8g")]       # measured before the rule: judged as before
    assert fc.check_envelope(old) == 0
